        const zerado = JSON.stringify(m.ovelha.infinito) === '{"plays":0,"bestScore":0,"bestEncontradas":0,"bestSequencia":0}';
        const preserva = m.ovelha.facil.plays === 3 && m.ovelha.apresentacaoDay === '2026-07-13' && m.pares.facil.plays === 1;
