        const m = { exports: {} }; fn(m, m.exports, CAT.MONTE_A_CENA_CATALOG, CAT.MONTE_A_CENA_STORY_ORDER, CAT.MONTE_A_CENA_TOTALS, CAT.MONTE_A_CENA_BLOCKED, CAT.isFreePuzzleStory, () => 'img');
